def test_scope_function_route():
    call_count = 0

    def my_dependency_route():
        nonlocal call_count
        call_count += 1
        return "dep"

    app = FastAPI()

    @app.get("/", dependencies=[Depends(my_dependency_route, scope="function")])
    def read_root_route():
        return {"msg": "ok"}

    client = TestClient(app)

    call_count = 0
    client.get("/")
    client.get("/")
